 static void Add(Transaction t,BlockTableRecord b,Entity e){e.ColorIndex=256;b.AppendEntity(e);t.AddNewlyCreatedDBObject(e,true);}
 static ObjectId Layer(Database db,Transaction t,string name,Color color,bool plot=true){var layers=(LayerTable)t.GetObject(db.LayerTableId,OpenMode.ForRead);if(layers.Has(name))return layers[name];layers.UpgradeOpen();var l=new LayerTableRecord{Name=name,Color=color,IsPlottable=plot,LineWeight=LineWeight.LineWeight013};var id=layers.Add(l);t.AddNewlyCreatedDBObject(l,true);return id;}
 static Point2d Paper(Viewport v,Point2d p){var d=(p-new Point2d(v.ViewTarget.X,v.ViewTarget.Y)).RotateBy(v.TwistAngle);return new Point2d(v.CenterPoint.X+(d.X-v.ViewCenter.X)*v.CustomScale,v.CenterPoint.Y+(d.Y-v.ViewCenter.Y)*v.CustomScale);}
 static bool In(Extents3d b,double x0,double y0,double x1,double y1)=>b.MinPoint.X>=x0&&b.MaxPoint.X<=x1&&b.MinPoint.Y>=y0&&b.MaxPoint.Y<=y1;
 static List<string> Geometry(Database db,Transaction t){var ms=(BlockTableRecord)t.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);return ms.Cast<ObjectId>().Select(id=>t.GetObject(id,OpenMode.ForRead)).Where(e=>e is Tin||e is Alignment||e is CivilProfile).Select(e=>e.Handle+" "+e.GetType().Name+(e is Alignment a?" L="+a.Length.ToString("R",CultureInfo.InvariantCulture):e is CivilProfile p?" S="+p.StartingStation.ToString("R",CultureInfo.InvariantCulture)+" E="+p.EndingStation.ToString("R",CultureInfo.InvariantCulture)+" MIN="+p.ElevationMin.ToString("R",CultureInfo.InvariantCulture)+" MAX="+p.ElevationMax.ToString("R",CultureInfo.InvariantCulture):"")).OrderBy(s=>s).ToList();}
 static bool Inside(Point2d p,Point2d[] poly){bool q=false;for(int i=0,j=poly.Length-1;i<poly.Length;j=i++){var a=poly[i];var b=poly[j];if((a.Y>p.Y)!=(b.Y>p.Y)&&p.X<(b.X-a.X)*(p.Y-a.Y)/(b.Y-a.Y)+a.X)q=!q;}return q;}
 static Point2d XY(Alignment a,double s){double x=0,y=0;a.PointLocation(s,0,ref x,ref y);return new Point2d(x,y);}
 static List<double[]> Crossings(Alignment a,Point2d[] polygon){var spans=new List<double[]>();double start=a.StartingStation,end=a.EndingStation;double step=.1,open=double.NaN,previous=start;bool was=Inside(XY(a,start),polygon);if(was)open=start;for(double s=Math.Min(start+step,end);;s=Math.Min(s+step,end)){bool now=Inside(XY(a,s),polygon);if(now!=was){double lo=previous,hi=s;for(int k=0;k<30;k++){double mid=(lo+hi)/2;if(Inside(XY(a,mid),polygon)==was)lo=mid;else hi=mid;}double cross=(lo+hi)/2;if(now)open=cross;else if(!double.IsNaN(open)){spans.Add(new[]{open,cross});open=double.NaN;}}if(s>=end-1e-9)break;previous=s;was=now;}if(!double.IsNaN(open))spans.Add(new[]{open,end});return spans;}
 static Point2d Map(State s,double station,double z)=>new Point2d(s.OX+(station-s.Start)*5,s.OY+(z-s.Min)*5);
