 foreach(var ax in new[]{st.LeftAxis,st.RightAxis}){ax.MajorTickStyle.Interval=5;ax.MinorTickStyle.Interval=5;ax.MajorTickStyle.TextHeight=.0036;ax.MajorTickStyle.LabelText="<[Profile View Point Elevation(Um|P0|RN|AP|GS|U3|Sn|OLD)]>";ax.TitleStyle.Text="ELEVACIÓN (m s.n.m.)";ax.TitleStyle.TextHeight=.0036;}
 st.LeftAxis.TitleStyle.OffsetX=-.023;st.RightAxis.TitleStyle.OffsetX=.026;st.BottomAxis.MajorTickStyle.Interval=5;st.BottomAxis.MajorTickStyle.LabelText="<[Station Value(Um|FD|P0|RN|AP|Sn|OF)]>m";st.BottomAxis.MajorTickStyle.TextHeight=.0036;st.BottomAxis.MajorTickStyle.OffsetY=-.004;st.BottomAxis.TitleStyle.Text="DISTANCIA (m)";st.BottomAxis.TitleStyle.TextHeight=.0036;st.BottomAxis.TitleStyle.OffsetY=-.013;
 foreach(ProfileViewDisplayStyleType c in Enum.GetValues(typeof(ProfileViewDisplayStyleType))){var display=st.GetDisplayStylePlan(c);string n=c.ToString();if(n.Contains("Minor")||n=="GraphTitle"||n.StartsWith("TopAxis")&&n!="TopAxis"||n.Contains("HGP"))display.Visible=false;if(n=="BottomAxis"||n=="BottomAxisTitle"||n=="BottomAxisAnnotationMajor"||n=="BottomAxisTicksMajor"||n=="LeftAxis"||n=="LeftAxisTitle"||n=="LeftAxisAnnotationMajor"||n=="RightAxis"||n=="RightAxisTitle"||n=="RightAxisAnnotationMajor")display.Visible=true;if(n.Contains("Grid")&&!n.Contains("Minor")||n=="TopAxis"){display.Color=Color.FromRgb(175,175,175);display.Lineweight=LineWeight.LineWeight005;if(n.Contains("Grid")){display.Visible=true;}}}
