 static void Dump(List<string> log,object o,string name,int depth){if(o==null)return;log.Add("OBJECT "+name+" "+o.GetType().FullName);foreach(var p in o.GetType().GetProperties().Where(p=>p.GetIndexParameters().Length==0)){try{var v=p.GetValue(o,null);log.Add(name+"."+p.Name+" ["+p.PropertyType.Name+"] write="+p.CanWrite+" = "+v);if(p.PropertyType.IsEnum)log.Add("ENUM "+p.Name+" "+string.Join(",",Enum.GetNames(p.PropertyType)));if(depth>0&&v!=null&&p.PropertyType.Namespace!=null&&p.PropertyType.Namespace.StartsWith("Autodesk.Civil")&&!p.PropertyType.IsEnum)Dump(log,v,name+"."+p.Name,depth-1);}catch{}}}
 [CommandMethod("PROFILEPHOTOFINAL")]
 public void Final(){System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;LayoutManager.Current.CurrentLayout=LayoutName;using(var t=db.TransactionManager.StartTransaction()){var geometry=Geometry(db,t);var ps=(BlockTableRecord)t.GetObject(((Layout)t.GetObject(LayoutManager.Current.GetLayoutId(LayoutName),OpenMode.ForRead)).BlockTableRecordId,OpenMode.ForRead);var objects=ps.Cast<ObjectId>().Select(id=>t.GetObject(id,OpenMode.ForRead)).ToArray();var v=objects.OfType<Viewport>().Single(p=>p.Width>560&&p.Width<580&&p.CenterPoint.Y<350);v.UpgradeOpen();v.Locked=false;v.Width=590;v.ViewHeight=v.Height/5;v.CustomScale=5;v.Locked=true;if(Code=="010")foreach(var d in objects.OfType<RotatedDimension>().Where(d=>d.Layer=="PERFILES_FOTO_COTAS_REALES")){d.UpgradeOpen();d.DimLinePoint+=new Vector3d(0,8,0);d.RecomputeDimensionBlock(true);}if(!geometry.SequenceEqual(Geometry(db,t)))throw new InvalidOperationException("Geometría alterada");t.Commit();}
 var dir=Path.Combine(Root,"PerfilesEntrega");Directory.CreateDirectory(dir);doc.Editor.Regen();FourFinish.Plot(db,Path.Combine(dir,"1107.001.00.14-200-14-P-"+Code+"-PERFILES.pdf"));db.SaveAs(Path.Combine(dir,"1107.001.00.14-200-14-P-"+Code+"-PERFILES.dwg"),DwgVersion.Current);doc.Editor.WriteMessage("\nPROFILEPHOTOFINAL_DONE "+Code+"\n");}
 [CommandMethod("PROFILEPHOTOVERIFY")]
 public void Check(){System.Diagnostics.Process.GetCurrentProcess().PriorityClass=System.Diagnostics.ProcessPriorityClass.BelowNormal;var doc=App.DocumentManager.MdiActiveDocument;var db=doc.Database;var logs=new List<string>();using(var t=db.TransactionManager.StartTransaction()){var expected=File.ReadAllLines(Path.Combine(Root,"photo-geometry-"+Code+".txt"));if(!expected.SequenceEqual(Geometry(db,t)))throw new InvalidOperationException("Geometría original distinta después de reabrir");logs.Add("GEOMETRÍA NATIVA VERIFICADA: "+expected.Length+" superficies, alineamientos y perfiles, sin cambios");var ps=(BlockTableRecord)t.GetObject(((Layout)t.GetObject(LayoutManager.Current.GetLayoutId(LayoutName),OpenMode.ForRead)).BlockTableRecordId,OpenMode.ForRead);var viewport=ps.Cast<ObjectId>().Select(id=>t.GetObject(id,OpenMode.ForRead)).OfType<Viewport>().Single(v=>v.Width>560&&v.Width<610&&v.CenterPoint.Y<350);if(Math.Abs(viewport.CustomScale-5)>1e-8)throw new InvalidOperationException("Escala de perfiles incorrecta");var ms=(BlockTableRecord)t.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(db),OpenMode.ForRead);var model=ms.Cast<ObjectId>().Select(id=>t.GetObject(id,OpenMode.ForRead)).ToArray();int visibleViews=0;foreach(var pv in model.OfType<PV>()){var b=pv.GeometricExtents;var q=Paper(viewport,new Point2d((b.MinPoint.X+b.MaxPoint.X)/2,(b.MinPoint.Y+b.MaxPoint.Y)/2));if(q.X<25||q.X>610||q.Y<100||q.Y>330)continue;visibleViews++;foreach(var bands in new[]{pv.Bands.GetBottomBandItems(),pv.Bands.GetTopBandItems()})foreach(var band in bands){var style=t.GetObject(band.BandStyleId,OpenMode.ForRead);foreach(var method in style.GetType().GetMethods().Where(m=>m.Name=="GetDisplayStylePlan"&&m.GetParameters().Length==1&&m.GetParameters()[0].ParameterType.IsEnum))foreach(var part in Enum.GetValues(method.GetParameters()[0].ParameterType)){var display=method.Invoke(style,new[]{part});if((bool)display.GetType().GetProperty("Visible").GetValue(display,null))throw new InvalidOperationException("Componente de banda visible");}}logs.Add("PERFIL "+pv.Name+": sin bandas visibles, escala 1:200, datos conservados");}if(visibleViews!=2)throw new InvalidOperationException("No se verificaron dos perfiles");foreach(var s in model.OfType<Tin>().Where(s=>s.Name=="TERRENO EXISTENTE"||s.Name==(Code=="010"?"Poza de agua":"Pozas"))){if(s.IsReferenceObject&&!s.IsReferenceValid||s.GetTriangles(false).Count==0)throw new InvalidOperationException("TIN no disponible "+s.Name);logs.Add("TIN VÁLIDO "+s.Name+" TRIÁNGULOS="+s.GetTriangles(false).Count);}int dimensions=0,distances=0;foreach(ObjectId id in ps){var e=t.GetObject(id,OpenMode.ForRead);if(e is Dimension d&&d.Layer=="PERFILES_FOTO_COTAS_REALES"){if(!string.IsNullOrEmpty(d.DimensionText))throw new InvalidOperationException("Cota con texto forzado");dimensions++;}if(e is MText m&&m.Layer=="PERFILES_FOTO_DISTANCIAS"){distances++;if(m.Text.Contains("DISTANCIA"))logs.Add("EJE DISTANCIA (m) VERIFICADO");}}if(dimensions<2||distances<6)throw new InvalidOperationException("Faltan cotas o distancias");logs.Add("COTAS REALES: "+dimensions+", dimensiones geométricas sin texto forzado");}
 File.WriteAllLines(Path.Combine(Root,"PerfilesEntrega","REAPERTURA-PERFILES-"+Code+".txt"),logs);doc.Editor.WriteMessage("\nPROFILEPHOTOVERIFY_DONE "+Code+"\n");}
 [CommandMethod("PROFILESTYLEPROBE")]
 public void Probe(){var doc=App.DocumentManager.MdiActiveDocument;var log=new List<string>();using(var tr=doc.Database.TransactionManager.StartTransaction()){var ms=(BlockTableRecord)tr.GetObject(SymbolUtilityServices.GetBlockModelSpaceId(doc.Database),OpenMode.ForRead);var pv=ms.Cast<ObjectId>().Select(id=>tr.GetObject(id,OpenMode.ForRead)).OfType<PV>().First();Dump(log,pv,"PV",0);var style=(ProfileViewStyle)tr.GetObject(pv.StyleId,OpenMode.ForRead);Dump(log,style,"STYLE",2);Dump(log,pv.Bands,"BANDS",1);foreach(var m in pv.Bands.GetType().GetMethods().Where(m=>m.DeclaringType==pv.Bands.GetType()))log.Add("BAND_METHOD "+m);var collection=pv.Bands.GetBottomBandItems();foreach(var m in collection.GetType().GetMethods())log.Add("COLLECTION_METHOD "+m);foreach(var band in collection){Dump(log,band,"BAND_ITEM",0);var bs=tr.GetObject(band.BandStyleId,OpenMode.ForRead);foreach(var method in bs.GetType().GetMethods().Where(q=>q.Name.Contains("DisplayStyle"))){log.Add("BAND_STYLE_API "+method);foreach(var par in method.GetParameters())if(par.ParameterType.IsEnum)log.Add("BAND_STYLE_ENUM "+string.Join(",",Enum.GetNames(par.ParameterType)));}}}
 File.WriteAllLines(Path.Combine(Root,"profile-style-api.txt"),log);doc.Editor.WriteMessage("\nPROFILESTYLEPROBE_DONE\n");}
